// The agreement as shown in one app: only that app's own name.
String licenseTextFor(String app) {
  final t = utf8.decode(base64.decode(_b64));
  return t
      .replaceAll('WORKFLOW, CHAT, PDF, SHEETS, CODE, REMOTE, LOGIN', app)
      .replaceAll('"Innovate", "WORKFLOW", "CHAT", "PDF", "SHEETS", "CODE", "REMOTE", "LOGIN"', '"Innovate", "' + app + '"');
}
